Q: Writing text and DarkMode don’t work together A: <p>✅ Removed global variable resets that were colliding with the typing effect
✅ Kept var i local inside getCookie() — it doesn't affect typing
✅ Moved checkCookie() call inside window.onload so it runs at the right time
✅ Removed duplicate checkbox line that served no purpose</p>
<p>This is Sample Code</p>
<pre><code>&lt;!DOCTYPE html&gt;
&lt;html lang=&quot;en&quot;&gt;
&lt;head&gt;
    &lt;meta charset=&quot;UTF-8&quot;&gt;
    &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;
    &lt;title&gt;Typing Effect + Dark Mode&lt;/title&gt;
    &lt;link rel=&quot;stylesheet&quot; href=&quot;https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css&quot;&gt;
    &lt;script src=&quot;https://code.jquery.com/jquery-3.6.0.min.js&quot;&gt;&lt;/script&gt;
    &lt;style&gt;
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            min-height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
            transition: background 0.3s ease;
        }

        body.dark-mode {
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
        }

        .container {
            text-align: center;
            padding: 40px;
            background: white;
            border-radius: 15px;
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
            max-width: 600px;
            width: 100%;
            transition: background 0.3s ease, color 0.3s ease;
        }

        body.dark-mode .container {
            background: #2d2d44;
            color: #e0e0e0;
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
        }

        .heading {
            margin-bottom: 30px;
        }

        .headP {
            font-size: 18px;
            color: #666;
            margin-bottom: 10px;
        }

        body.dark-mode .headP {
            color: #a0a0a0;
        }

        h1 {
            font-size: 48px;
            color: #333;
            font-weight: 600;
            margin: 20px 0;
            min-height: 60px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        body.dark-mode h1 {
            color: #fff;
        }

        .typewrite {
            text-decoration: none;
            color: #667eea;
            font-weight: 700;
        }

        body.dark-mode .typewrite {
            color: #7c9eff;
        }

        .typewrite &gt; .wrap {
            border-right: 0.08em solid #667eea;
            animation: blink-caret 0.75s step-end infinite;
        }

        body.dark-mode .typewrite &gt; .wrap {
            border-right: 0.08em solid #7c9eff;
        }

        @keyframes blink-caret {
            from, to { border-color: transparent; }
            50% { border-color: currentColor; }
        }

        /* Dark Mode Toggle */
        .dark-mode-section {
            margin-top: 40px;
            padding-top: 30px;
            border-top: 2px solid #eee;
        }

        body.dark-mode .dark-mode-section {
            border-top: 2px solid #444;
        }

        .dark {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 15px;
        }

        .fotxt2 {
            font-size: 16px;
            color: #666;
            margin: 0;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        body.dark-mode .fotxt2 {
            color: #a0a0a0;
        }

        /* Toggle Switch */
        .switch {
            position: relative;
            display: inline-block;
            width: 60px;
            height: 34px;
        }

        .switch input {
            opacity: 0;
            width: 0;
            height: 0;
        }

        .slider {
            position: absolute;
            cursor: pointer;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: #ccc;
            transition: 0.4s;
            border-radius: 34px;
        }

        .slider:before {
            position: absolute;
            content: &quot;&quot;;
            height: 26px;
            width: 26px;
            left: 4px;
            bottom: 4px;
            background-color: white;
            transition: 0.4s;
            border-radius: 50%;
        }

        input:checked + .slider {
            background-color: #2196F3;
        }

        input:checked + .slider:before {
            transform: translateX(26px);
        }

        .slider.round {
            border-radius: 34px;
        }

        .slider.round:before {
            border-radius: 50%;
        }

        /* Additional Styling */
        .info {
            margin-top: 30px;
            font-size: 14px;
            color: #999;
        }

        body.dark-mode .info {
            color: #666;
        }
    &lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
    &lt;div class=&quot;container&quot;&gt;
        &lt;!-- Typing Effect Section --&gt;
        &lt;div class=&quot;heading&quot;&gt;
            &lt;p class=&quot;headP&quot;&gt;Welcome, I am&lt;/p&gt;
            &lt;h1&gt;
                &lt;a href=&quot;#&quot; class=&quot;typewrite h11&quot; data-period=&quot;2000&quot; data-type='[ &quot;MartanKing.&quot;, &quot;Fullstack Developer.&quot;, &quot;Junior WebMaster.&quot;, &quot;WebDesigner.&quot; ]'&gt;
                    &lt;span class=&quot;wrap&quot;&gt;&lt;/span&gt;
                &lt;/a&gt;
            &lt;/h1&gt;
        &lt;/div&gt;

        &lt;!-- Dark Mode Toggle Section --&gt;
        &lt;div class=&quot;dark-mode-section&quot;&gt;
            &lt;div class=&quot;dark&quot;&gt;
                &lt;p class=&quot;fotxt2&quot;&gt;&lt;i class=&quot;fas fa-adjust&quot;&gt;&lt;/i&gt; Dark Mode&lt;/p&gt;
                &lt;label class=&quot;switch&quot;&gt;
                    &lt;input type=&quot;checkbox&quot; onclick=&quot;darkMode()&quot; class=&quot;darktogg&quot; id=&quot;switching&quot;&gt;
                    &lt;span class=&quot;slider round&quot;&gt;&lt;/span&gt;
                &lt;/label&gt;
            &lt;/div&gt;
        &lt;/div&gt;

        &lt;div class=&quot;info&quot;&gt;
            &lt;p&gt;Click the toggle to switch between light and dark mode&lt;/p&gt;
        &lt;/div&gt;
    &lt;/div&gt;

    &lt;!-- JavaScript --&gt;
    &lt;script&gt;
        // ========================================
        // DARK MODE - CHECK COOKIE ON PAGE LOAD
        // ========================================

        // Get cookie value
        function getCookie(cname) {
            var name = cname + &quot;=&quot;;
            var decodedCookie = decodeURIComponent(document.cookie);
            var ca = decodedCookie.split(';');

            // Keep 'i' LOCAL to this function only
            for(var i = 0; i &lt; ca.length; i++) {
                var c = ca[i];
                while (c.charAt(0) == ' ') {
                    c = c.substring(1);
                }
                if (c.indexOf(name) == 0) {
                    return c.substring(name.length, c.length);
                }
            }
            return &quot;&quot;;
        }

        // Set cookie value
        function setCookie(cname, cvalue, exdays) {
            var d = new Date();
            d.setTime(d.getTime() + (exdays * 24 * 60 * 60 * 1000));
            var expires = &quot;expires=&quot; + d.toUTCString();
            document.cookie = cname + &quot;=&quot; + cvalue + &quot;;&quot; + expires + &quot;;path=/&quot;;
        }

        // Check cookie on page load
        function checkCookie() {
            var dmTheme = getCookie(&quot;darkmode&quot;);
            if (dmTheme === &quot;active&quot;) {
                console.log(&quot;Darkmode is &quot; + dmTheme);
                $(&quot;#switching&quot;).prop(&quot;checked&quot;, true);
                darkMode();
            } else {
                console.log(&quot;Darkmode is off&quot;);
                $(&quot;#switching&quot;).prop(&quot;checked&quot;, false);
            }
        }

        // Toggle dark mode
        function darkMode() {
            var darkModeCheckbox = $(&quot;#switching&quot;);

            if (darkModeCheckbox.prop(&quot;checked&quot;)) {
                // Enable Dark Mode
                $(&quot;body&quot;).addClass(&quot;dark-mode&quot;);
                setCookie(&quot;darkmode&quot;, &quot;active&quot;, 365);
                console.log(&quot;Dark mode enabled&quot;);
            } else {
                // Disable Dark Mode
                $(&quot;body&quot;).removeClass(&quot;dark-mode&quot;);
                setCookie(&quot;darkmode&quot;, &quot;inactive&quot;, 365);
                console.log(&quot;Dark mode disabled&quot;);
            }
        }


        // ========================================
        // TYPING EFFECT - TEXT ROTATION
        // ========================================

        var TxtType = function(el, toRotate, period) {
            this.toRotate = toRotate;
            this.el = el;
            this.loopNum = 0;
            this.period = parseInt(period, 10) || 2000;
            this.txt = '';
            this.tick();
            this.isDeleting = false;
        };

        TxtType.prototype.tick = function() {
            var i = this.loopNum % this.toRotate.length;
            var fullTxt = this.toRotate[i];

            if (this.isDeleting) {
                this.txt = fullTxt.substring(0, this.txt.length - 1);
            } else {
                this.txt = fullTxt.substring(0, this.txt.length + 1);
            }

            this.el.innerHTML = '&lt;span class=&quot;wrap&quot;&gt;' + this.txt + '&lt;/span&gt;';

            var that = this;
            var delta = 200 - Math.random() * 100;

            if (this.isDeleting) { 
                delta /= 2; 
            }

            if (!this.isDeleting &amp;&amp; this.txt === fullTxt) {
                delta = this.period;
                this.isDeleting = true;
            } else if (this.isDeleting &amp;&amp; this.txt === '') {
                this.isDeleting = false;
                this.loopNum++;
                delta = 500;
            }

            setTimeout(function() {
                that.tick();
            }, delta);
        };

        // Initialize everything on page load
        window.onload = function() {
            // 1. Check and apply saved dark mode preference
            checkCookie();

            // 2. Initialize all typing effect elements
            var elements = document.getElementsByClassName('typewrite');
            for (var i = 0; i &lt; elements.length; i++) {
                var toRotate = elements[i].getAttribute('data-type');
                var period = elements[i].getAttribute('data-period');
                if (toRotate) {
                    new TxtType(elements[i], JSON.parse(toRotate), period);
                }
            }

            // 3. Add cursor style for typing effect
            var css = document.createElement(&quot;style&quot;);
            css.type = &quot;text/css&quot;;
            css.innerHTML = &quot;.typewrite &gt; .wrap { border-right: 0.08em solid #667eea; }&quot;;
            document.body.appendChild(css);
        };
    &lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>

Q: HTML align items and font color A: <pre><code>&lt;!DOCTYPE html&gt;
&lt;html lang=&quot;it&quot;&gt;
&lt;head&gt;
    &lt;title&gt;Empire Audio System&lt;/title&gt;
    &lt;style&gt;
        body { background: #0a0a0a; color: #d4af37; font-family: 'Inter', sans-serif; display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100vh; margin: 0; }
        #status { border: 1px solid #d4af37; padding: 20px; border-radius: 8px; text-align: center; }
        .glitch { animation: shake 0.5s infinite; color: red; }
        @keyframes shake { 0% { transform: translate(0); } 20% { transform: translate(-2px, 2px); } 40% { transform: translate(-2px, -2px); } 60% { transform: translate(2px, 2px); } 80% { transform: translate(2px, -2px); } 100% { transform: translate(0); } }
    &lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;

    &lt;div id=&quot;status&quot;&gt;
        &lt;h1&gt;Sistema Imperiale&lt;/h1&gt;
        &lt;p id=&quot;message&quot;&gt;In attesa di eventi...&lt;/p&gt;
        &lt;button id=&quot;startBtn&quot;&gt;Attiva Audio&lt;/button&gt;
    &lt;/div&gt;

    &lt;script&gt;
        const EmpireAudio = {
            ctx: null,
            init() {
                if (!this.ctx) {
                    this.ctx = new (window.AudioContext || window.webkitAudioContext)();
                }
            },
            playSuccess() {
                this.init();
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                osc.type = 'triangle';
                osc.connect(gain);
                gain.connect(this.ctx.destination);
                const now = this.ctx.currentTime;
                osc.frequency.setValueAtTime(440, now);
                osc.frequency.exponentialRampToValueAtTime(880, now + 0.5);
                gain.gain.setValueAtTime(0.1, now);
                gain.gain.exponentialRampToValueAtTime(0.01, now + 0.5);
                osc.start(now);
                osc.stop(now + 0.5);
            },
            playWarning() {
                this.init();
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                osc.type = 'sawtooth';
                osc.connect(gain);
                gain.connect(this.ctx.destination);
                const now = this.ctx.currentTime;
                osc.frequency.setValueAtTime(150, now);
                osc.frequency.linearRampToValueAtTime(50, now + 0.3);
                gain.gain.setValueAtTime(0.1, now);
                gain.gain.linearRampToValueAtTime(0, now + 0.3);
                osc.start(now);
                osc.stop(now + 0.3);
            }
        };

        // Collegamento SSE
        const startBtn = document.getElementById('startBtn');
        const msg = document.getElementById('message');

        startBtn.onclick = () =&gt; {
            EmpireAudio.init(); // Sblocca l'audio
            startBtn.style.display = 'none';
            msg.innerText = &quot;Audio Attivo. In ascolto dal server...&quot;;

            const eventSource = new EventSource('http://localhost:3000/events');

            eventSource.onmessage = (event) =&gt; {
                const { type, payload } = JSON.parse(event.data);

                if (type === 'CREDITS_ADD') {
                    msg.innerHTML = `&lt;span style=&quot;color: gold;&quot;&gt;+${payload.amount} CREDITI! (Totale: ${payload.newTotal})&lt;/span&gt;`;
                    setTimeout(() =&gt; EmpireAudio.playSuccess(), 150);
                }

                if (type === 'ACCESS_REVOKED') {
                    msg.innerHTML = `&lt;span class=&quot;glitch&quot;&gt;ACCESSO REVOCATO - GHIGLIOTTINA&lt;/span&gt;`;
                    EmpireAudio.playWarning();
                }
            };
        };
    &lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>
